import type { L10n, PriorityId } from '../types';
import type { Effects, GameDecision, GameOption } from './president-levels.ts';

/*
 * The decisions of « Si m te prezidan » v4, grouped by level. Fifteen come from the prototype
 * (docs/si-m-te-prezidan-prototype.html); twelve are the earlier scenarios of the site that fit a
 * level, rescaled to the same numbers (a cost for the treasury, smaller effects). Each run draws three
 * per level (see LEVELS[].slots), so terms differ. Invented scenarios: no real candidate or party.
 */

const T = (ht: string, fr: string, en: string): L10n => ({ ht, fr, en });
interface Extra { flag?: string; p?: PriorityId; p2?: PriorityId }
const o = (t: L10n, d: L10n, cost: number, e: Effects, h: L10n, w: L10n, x: Extra = {}): GameOption => ({ t, d, cost, e, h, w, ...x });

